def run(values):
    if len(values) < 3:
        return None
    slopes = []
    for i in range(len(values)):
        for j in range(i+1, len(values)):
            slopes.append((values[j]-values[i])/(j-i))
    slopes = sorted(slopes)
    n = len(slopes)
    if n % 2 == 1:
        return slopes[n//2]
    return (slopes[n//2-1]+slopes[n//2])/2
